```openscad
// Round-bottom flask support ring on three legs
// Print orientation: legs on bed at z = 0, ring at top

$fn = 96;

// ---- Ring ----
ring_od      = 90;   // ring outer diameter
ring_id      = 66;   // ring inner diameter
ring_t       = 6;    // ring thickness
ring_top_z   = 60;   // z of ring top face

// ---- Legs ----
leg_d        = 6;    // leg diameter
leg_circle_d = 78;   // diameter of circle through leg axes
leg_count    = 3;    // number of legs
leg_start_a  = 0;    // angle of first leg (on +X axis)
leg_overlap  = 0.5;  // how far legs extend into ring for a solid union

// ---- Derived ----
ring_bot_z   = ring_top_z - ring_t;
eps          = 0.5;  // cutter overrun past faces

union() {
    // Flat annular ring
    translate([0, 0, ring_bot_z])
        difference() {
            cylinder(d = ring_od, h = ring_t);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_t + 2 * eps);
        }

    // Legs, straight down from the ring to the bed
    for (i = [0 : leg_count - 1]) {
        a = leg_start_a + i * 360 / leg_count;
        translate([leg_circle_d / 2 * cos(a), leg_circle_d / 2 * sin(a), 0])
            cylinder(d = leg_d, h = ring_bot_z + leg_overlap);
    }
}
```

