// Spacer with counterbored socket-head screw hole
// Print orientation: standing on bed, z = 0 to 15, centred on origin

$fn = 96;               // curve resolution

// Main body
body_d      = 16;       // outer diameter of spacer
body_h      = 15;       // total height of spacer

// Through hole
hole_d      = 3.4;      // clearance hole diameter (full height)

// Counterbore (from top face)
cbore_d     = 6.5;      // counterbore diameter
cbore_depth = 5;        // counterbore depth from top (z = 10 to 15)

// Cut overshoot to avoid coplanar faces
eps         = 0.5;      // extension of cutting shapes past faces

difference() {
    // Main cylindrical body
    cylinder(d = body_d, h = body_h);

    // Through hole along the axis
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = body_h + 2 * eps);

    // Counterbore from top face down to z = body_h - cbore_depth
    translate([0, 0, body_h - cbore_depth])
        cylinder(d = cbore_d, h = cbore_depth + eps);
}
