```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate on bed (z = 0), rail on top building upward.

$fn = 64;

// ---------------- Dimensions (mm) ----------------
plate_len     = 120;   // base plate length (X)
plate_wid     = 36;    // base plate width (Y)
plate_thk     = 5;     // base plate thickness (Z), z = 0..5

rail_len      = plate_len; // rail runs full length of plate (X)
rail_w_bottom = 12;    // rail width where it meets plate (z = 5)
rail_w_top    = 16;    // rail width at top face (z = 11)
rail_top_z    = 11;    // rail top face height
rail_h        = rail_top_z - plate_thk; // rail height = 6

overlap       = 0.01;  // small embed of rail into plate for a clean union

// ---------------- Modules ----------------
module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

// Dovetail cross-section in the YZ plane (2D x -> Y, 2D y -> Z)
module rail_profile() {
    polygon(points = [
        [-rail_w_bottom/2, plate_thk - overlap], // embedded straight stub
        [ rail_w_bottom/2, plate_thk - overlap],
        [ rail_w_bottom/2, plate_thk],
        [ rail_w_top/2,    rail_top_z],
        [-rail_w_top/2,    rail_top_z],
        [-rail_w_bottom/2, plate_thk]
    ]);
}

module dovetail_rail() {
    // Extrude profile along X, centred on origin
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            rail_profile();
}

// ---------------- Part ----------------
union() {
    base_plate();
    dovetail_rail();
}
```

