                    [-rail_bot_wid/2, plate_thk - overlap],
                    [ rail_bot_wid/2, plate_thk - overlap],
                    [ rail_bot_wid/2, plate_thk],
                    [ rail_top_wid/2, rail_top_z],
                    [-rail_top_wid/2, rail_top_z],
