// Sliding mount with dovetail rail
// Print orientation: base plate flat on the bed, rail pointing up (+Z)

$fn = 64;

// ---------------- Dimensions (mm) ----------------
plate_len    = 60;   // base plate length (X)
plate_wid    = 30;   // base plate width (Y)
plate_thk    = 6;    // base plate thickness (Z), z = 0..6

rail_len     = plate_len; // rail runs the full plate length (X)
rail_w_base  = 10;   // dovetail width where it meets the plate (z = 6)
rail_w_top   = 14;   // dovetail width at its top face
rail_top_z   = 11;   // Z height of the rail top face

overlap      = 0.01; // small overlap so rail fuses into the plate

// ---------------- Derived ----------------
rail_h = rail_top_z - plate_thk;                              // 5 mm tall rail
// width at the overlap depth, following the same flank slope
rail_w_ovl = rail_w_base - (rail_w_top - rail_w_base) * overlap / rail_h;

// ---------------- Model ----------------
union() {
    // Base plate, centred in X/Y, z = 0..plate_thk
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: trapezoid in YZ, extruded along X
    // rotate([90,0,90]) maps 2D x -> Y, 2D y -> Z, extrusion -> X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_w_ovl/2, plate_thk - overlap],
                [ rail_w_ovl/2, plate_thk - overlap],
                [ rail_w_top/2, rail_top_z],
                [-rail_w_top/2, rail_top_z]
            ]);
}
