// Door wedge with vertical through-slot
// Print orientation: flat bottom face on the bed (z = 0), sloped face up.
// Positioned with the coordinates the user specified (not centred on the origin).

// ---------- Wedge dimensions ----------
wedge_length = 120;   // X: length of wedge base
wedge_width  = 40;    // Y: width of wedge (extrusion length)
wedge_height = 25;    // Z: height at the tall end (x = 0)

// ---------- Slot dimensions ----------
slot_width    = 6;    // Y: slot width
slot_length   = 30;   // X: slot length
slot_center_x = 60;   // X position of slot centre
slot_center_y = 20;   // Y position of slot centre

// ---------- Cutting clearance ----------
eps = 1;              // extension of cutters past the faces they cut

$fn = 64;

difference() {
    // Right-triangle wedge: XZ cross-section extruded along +Y from y = 0 to y = wedge_width
    translate([0, wedge_width, 0])
        rotate([90, 0, 0])
            linear_extrude(height = wedge_width)
                polygon(points = [
                    [0, 0],
                    [wedge_length, 0],
                    [0, wedge_height]
                ]);

    // Vertical straight slot through the whole wedge
    translate([slot_center_x - slot_length / 2,
               slot_center_y - slot_width / 2,
               -eps])
        cube([slot_length, slot_width, wedge_height + 2 * eps]);
}
