// Glass stirring rod rest - rectangular block with 4 V-grooves across the top
// Print orientation: flat on bed, grooves facing up

// ---------- Parameters ----------
block_len   = 84;   // block length along X (mm)
block_wid   = 50;   // block width along Y (mm)
block_h     = 12;   // block height along Z (mm)

groove_n     = 4;   // number of V-grooves
groove_pitch = 18;  // centre-to-centre spacing of grooves along X (mm)
groove_w     = 8;   // groove width at top surface (mm)
groove_d     = 4;   // groove depth (mm) - 90 deg V: depth = width/2

ext = 0.5;          // overcut past faces to avoid coplanar faces (mm)

$fn = 64;

// ---------- Derived ----------
half_w = groove_w / 2;

// V-groove cutter: 2D profile in (X, Z), extruded along Y.
// Sides are extended above the top surface along the same 45 deg slope,
// so the groove stays exactly groove_w wide at z = block_h.
module v_groove_cutter() {
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * ext, center = true)
            polygon(points = [
                [-(half_w + ext), block_h + ext],
                [  half_w + ext,  block_h + ext],
                [  0,             block_h - groove_d]
            ]);
}

// ---------- Model ----------
difference() {
    // Main block, centred in X and Y, resting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_h]);

    // Grooves, centred along X
    for (i = [0 : groove_n - 1])
        translate([(i - (groove_n - 1) / 2) * groove_pitch, 0, 0])
            v_groove_cutter();
}
```

