// Rest for glass stirring rods - rectangular block with V-grooves across the top

// ---------------- Parameters ----------------
block_len    = 99;    // block length along X (mm)
block_wid    = 40;    // block width along Y (mm)
block_h      = 12;    // block height along Z (mm)

groove_count = 6;     // number of V-grooves
groove_pitch = 15;    // centre-to-centre spacing of grooves along X (mm)
groove_w     = 8;     // groove width at the top surface (mm)
groove_d     = 4;     // groove depth (mm) - 90 deg V: depth = width/2

ext          = 0.5;   // overcut past faces to avoid coplanar faces (mm)

$fn = 64;

// ---------------- Derived ----------------
groove_span = (groove_count - 1) * groove_pitch;   // distance between outer groove centres

// ---------------- Modules ----------------
// One V-groove cutter, centred at x = 0, running along Y.
// The 45-degree sides are extended above the top face by 'ext'.
module v_groove() {
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * ext, center = true)
            polygon(points = [
                [-(groove_w / 2 + ext), block_h + ext],   // top left (above surface)
                [  groove_w / 2 + ext,  block_h + ext],   // top right (above surface)
                [0, block_h - groove_d]                   // bottom of V
            ]);
}

// ---------------- Model ----------------
difference() {
    // Main block, centred in X and Y, resting on z = 0
