    // Plus-shaped plate
    union() {
        translate([-arm_length/2, -arm_width/2, 0])
            cube([arm_length, arm_width, plate_thickness]);
        translate([-arm_width/2, -arm_length/2, 0])
            cube([arm_width, arm_length, plate_thickness]);
    }

    // Centre hole
    translate([0, 0, -cut_extra])
        cylinder(d = hole_d, h = plate_thickness + 2*cut_extra);

    // Arm-end holes (4x, every 90 degrees)
    for (a = [0 : 90 : 270])
        rotate([0, 0, a])
            translate([hole_offset, 0, -cut_extra])
                cylinder(d = hole_d, h = plate_thickness + 2*cut_extra);
}
