// ---------------- Model ----------------
// Profile in the XZ plane, extruded along +Y.
// Each step i spans x = i*step_length .. (i+1)*step_length and is solid
// from the bed (z = 0) up to z = (i+1)*step_rise.
module stepped_riser() {
    // Profile polygon (X, Z) built with a loop, then extruded along Y
    pts = concat(
        [[0, 0]],
        [for (i = [0 : num_steps - 1]) each [
            [i * step_length,       (i + 1) * step_rise],
            [(i + 1) * step_length, (i + 1) * step_rise]
        ]],
        [[total_length, 0]]
    );

    // rotate([90,0,0]) maps extrusion axis (+Z) to -Y and polygon Y to +Z;
    // translate by depth so the part spans y = 0 .. depth.
    translate([0, depth, 0])
        rotate([90, 0, 0])
            linear_extrude(height = depth)
                polygon(points = pts);
}

stepped_riser();
