// Display base with 45-degree chamfered top edges
// Print orientation: bottom face on the bed (z = 0), builds upward (+Z)

// ---------------- Parameters ----------------
base_x    = 80;   // overall length in X (mm)
base_y    = 50;   // overall width in Y (mm)
base_z    = 15;   // overall height in Z (mm)
chamfer   = 2;    // 45-degree chamfer width/height on top edges (mm)
eps       = 0.01; // small overlap to avoid coplanar faces in unions

// Derived dimensions
side_z    = base_z - chamfer;     // height where vertical sides stop (13 mm)
top_x     = base_x - 2 * chamfer; // top face length (76 mm)
top_y     = base_y - 2 * chamfer; // top face width (46 mm)

// ---------------- Model ----------------
// Hull of the full-size footprint (up to z = 13) and the reduced
// top face slab (at z = 15) gives sharp bottom edges and 45-degree
// chamfers on all four top edges.
hull() {
    // Lower block with vertical sides, z = 0 .. 13
    translate([-base_x / 2, -base_y / 2, 0])
        cube([base_x, base_y, side_z]);

    // Thin slab defining the top face, 76 x 46 at z = 15
    translate([-top_x / 2, -top_y / 2, base_z - eps])
        cube([top_x, top_y, eps]);
